33|function useDuckRamp(target: number): number {
34|  const [duck, setDuck] = useState(1);
35|  const duckRef = useRef(1);
36|  useEffect(() => {
37|    if (duckRef.current === target) {
38|      setDuck(target);
39|      return;
40|    }
41|    const duration = target < duckRef.current ? NARRATION_DUCK_DOWN_MS : NARRATION_DUCK_UP_MS;
42|    let raf = 0;
43|    let prev = performance.now();
44|    const tick = (now: number) => {
45|      const next = rampDuck(duckRef.current, target, now - prev, duration);
46|      prev = now;
47|      duckRef.current = next;
48|      setDuck(next);
49|      if (next !== target) raf = requestAnimationFrame(tick);
50|    };
51|    raf = requestAnimationFrame(tick);
52|    return () => cancelAnimationFrame(raf);
