29|const SENTENCE_HIGHLIGHT = "narration-sentence";
30|
31|function skinTreatment(): HighlightTreatment {
32|  try {
33|    return highlightStyleFor(document.documentElement.dataset.skin ?? "default");
34|  } catch {
35|    return "engraving";
36|  }
37|}
