39|export function useReadSync(opts: {
40|  enabled: boolean;
41|  audioRef: RefObject<HTMLAudioElement | null>;
42|  manifest: ChapterNarration | null;
43|  span: { startSec: number; endSec: number } | null;
44|  columnRef: RefObject<HTMLElement | null>;
