46|  const [treatment, setTreatment] = useState<HighlightTreatment>(skinTreatment);
47|  const [mark, setMark] = useState<MarkRect | null>(null);
48|  const [active, setActive] = useState<ActiveSpot | null>(null);
49|
50|  const live = useRef(opts);
51|  live.current = opts;
52|
53|  // A skin switch restyles the mark live: data-skin is picked whenever
54|  // it is available, with engraving as the default.
55|  useEffect(() => {
56|    const root = document.documentElement;
57|    const sync = () => setTreatment(skinTreatment());
58|    sync();
59|    const obs = new MutationObserver(sync);
60|    obs.observe(root, { attributes: true, attributeFilter: ["data-skin"] });
61|    return () => obs.disconnect();
62|  }, []);
63|
64|  // The follow loop runs only while the voice plays: play starts it,
65|  // pause stops it, so nothing animates while paused.
66|  useEffect(() => {
67|    const seen = live.current;
68|    if (!seen.enabled || !seen.manifest) {
69|      setActive(null);
70|      return;
71|    }
72|    const audio = seen.audioRef.current;
73|    if (!audio) return;
74|    let raf = 0;
75|    const tick = () => {
76|      raf = requestAnimationFrame(tick);
77|      // Every input is read live each tick: the scene (and its span)
78|      // can change under a kept chapter manifest, so a closed-over
79|      // span would gate the voice against the previous scene.
80|      const heard = live.current;
81|      if (!heard.enabled || !heard.manifest) return;
82|      const el = heard.audioRef.current;
83|      if (!el || el.paused) return;
84|      const t = el.currentTime;
85|      const span = heard.span;
86|      if (span !== null && (t < span.startSec - 0.3 || t > span.endSec + 2)) return;
87|      const ci = activeChunkAt(heard.manifest.chunks, t);
88|      if (ci < 0) {
89|        setActive((prev) => (prev === null ? prev : null));
90|        return;
91|      }
92|      const chunk = heard.manifest.chunks[ci] as ChapterNarration["chunks"][number];
93|      const wi = activeWordAt(chunk, t);
94|      setActive((prev) => (prev !== null && prev.chunk === ci && prev.word === wi ? prev : { chunk: ci, word: wi }));
