96|    const onPlay = () => {
97|      if (!raf) tick();
98|    };
99|    const onPause = () => {
100|      cancelAnimationFrame(raf);
101|      raf = 0;
102|    };
103|    audio.addEventListener("play", onPlay);
104|    audio.addEventListener("pause", onPause);
105|    if (!audio.paused) tick();
