107|      cancelAnimationFrame(raf);
108|      raf = 0;
109|      audio.removeEventListener("play", onPlay);
110|      audio.removeEventListener("pause", onPause);
111|    };
112|  }, [opts.enabled, opts.manifest]);
113|
