9|import { useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";
10|import { activeChunkAt, activeWordAt, wordAt, type ChapterNarration } from "@/core/narration";
11|import { followIntoView } from "../leer/scroll-helpers";
12|import { Icon } from "../icons";
13|import { engravingScale, highlightStyleFor, type HighlightTreatment } from "./highlight-style";
