306|// Map Kokoro word tokens onto every display word in `text`, in order.
307|// Display words come from DISPLAY_WORD_RE, so "Oz’s" and "didn't" are
308|// one word and quotes and punctuation are never highlighted. Returned
309|// offsets are relative to `text` (the caller adds the chunk's paragraph
310|// offset); times are chapter-absolute seconds, clamped to `span`.
311|// Matching tolerates a skipped or extra token, or a number Kokoro
312|// spells out, with a lookahead of 3 on either side; a token spanning
313|// several display words ("well-known") covers them all, splitting its
314|// time by character length. Words left without time interpolate between
315|// their neighbours, and every time ends monotonic inside the span.
316|export function alignWords(
317|  text: string,
318|  tokens: WordToken[],
319|  span: { t0: number; t1: number },
320|): [number, number, number, number][] {
321|  const display = [...text.matchAll(DISPLAY_WORD_RE)].map((m) => ({
322|    start: m.index ?? 0,
323|    end: (m.index ?? 0) + m[0].length,
324|    norm: normalizeWord(m[0]),
325|  }));
326|  const norms = tokens.map((t) => normalizeWord(t.text));
327|  const timed: ({ t0: number; t1: number } | null)[] = display.map(() => null);
328|  let i = 0;
329|  let j = 0;
330|  while (i < display.length) {
331|    while (j < tokens.length && norms[j] === "") j += 1;
332|    if (j >= tokens.length) break;
333|    const word = display[i] as { start: number; end: number; norm: string };
334|    const tok = tokens[j] as WordToken;
335|    if (word.norm === norms[j]) {
336|      timed[i] = { t0: tok.t0, t1: tok.t1 };
337|      i += 1;
338|      j += 1;
339|      continue;
340|    }
341|    // One token covering several display words: its norm is the
342|    // concatenation of theirs, joined without whitespace ("well-known").
343|    let joined = word.norm;
344|    let k = i;
