349|      joined += next.norm;
350|      k += 1;
351|      if (joined === norms[j]) break;
352|    }
353|    if (k > i && joined === norms[j]) {
354|      const total =
355|        display.slice(i, k + 1).reduce((sum, d) => sum + (d.end - d.start), 0) || 1;
356|      let edge = tok.t0;
357|      for (let m = i; m <= k; m++) {
358|        const part = display[m] as { start: number; end: number; norm: string };
359|        const share = ((part.end - part.start) / total) * (tok.t1 - tok.t0);
360|        timed[m] = { t0: edge, t1: edge + share };
361|        edge += share;
362|      }
363|      i = k + 1;
364|      j += 1;
365|      continue;
366|    }
