368|    for (let a = 1; a <= 3 && j + a < tokens.length; a++) {
369|      if (norms[j + a] === word.norm) {
370|        j += a;
371|        advanced = true;
372|        break;
373|      }
374|    }
375|    if (!advanced) {
376|      for (let b = 1; b <= 3 && i + b < display.length; b++) {
377|        if ((display[i + b] as { norm: string }).norm === norms[j]) {
378|          i += b;
379|          advanced = true;
380|          break;
381|        }
382|      }
383|    }
384|    if (advanced) continue;
385|    // Neither side matches (a number Kokoro spells out): both move on
386|    // and the display word interpolates below.
387|    i += 1;
388|    j += 1;
389|  }
390|  for (let a = 0; a < display.length; a++) {
391|    if (timed[a] !== null) continue;
392|    let b = a;
393|    while (b + 1 < display.length && timed[b + 1] === null) b += 1;
394|    const lo = a > 0 ? (timed[a - 1] as { t0: number; t1: number }).t1 : span.t0;
395|    const hi = b + 1 < display.length ? (timed[b + 1] as { t0: number; t1: number }).t0 : span.t1;
396|    const from = Math.min(lo, hi);
397|    const to = Math.max(lo, hi);
398|    const count = b - a + 1;
399|    for (let m = a; m <= b; m++) {
400|      timed[m] = { t0: from + ((to - from) * (m - a)) / count, t1: from + ((to - from) * (m - a + 1)) / count };
401|    }
402|    a = b;
403|  }
404|  const round3 = (v: number): number => Math.round(v * 1000) / 1000;
405|  const clamp = (v: number): number => Math.min(span.t1, Math.max(span.t0, v));
406|  let prevT0 = span.t0;
407|  return display.map((d, index) => {
408|    const t = timed[index] as { t0: number; t1: number };
409|    let t0 = clamp(round3(t.t0));
410|    let t1 = clamp(round3(t.t1));
411|    if (t0 < prevT0) t0 = prevT0;
412|    if (t1 < t0) t1 = t0;
413|    prevT0 = t0;
414|    return [d.start, d.end, t0, t1];
415|  });
416|}
