418|// Binary search: index of the last word with t0 <= t, so the highlight
419|// stays on a word through the gap after it. -1 before the first.
420|export function activeWordAt(chunk: { w: number[] }, tSec: number): number {
421|  const count = Math.floor(chunk.w.length / 4);
422|  let lo = 0;
423|  let hi = count - 1;
424|  let found = -1;
425|  while (lo <= hi) {
426|    const mid = (lo + hi) >> 1;
427|    if ((chunk.w[mid * 4 + 2] as number) <= tSec) {
428|      found = mid;
429|      lo = mid + 1;
430|    } else {
431|      hi = mid - 1;
432|    }
433|  }
434|  return found;
435|}
436|
437|// Click-to-seek: the word covering charOffset in paragraph n, with its
438|// chunk and word indexes and start time. Null when outside any word.
439|export function wordAt(
440|  narration: { chunks: { n: number; start: number; end: number; w: number[] }[] },
441|  n: number,
442|  charOffset: number,
443|): { chunk: number; word: number; t0: number } | null {
444|  for (let c = 0; c < narration.chunks.length; c++) {
445|    const chunk = narration.chunks[c] as { n: number; start: number; end: number; w: number[] };
446|    if (chunk.n !== n || charOffset < chunk.start || charOffset >= chunk.end) continue;
447|    const count = Math.floor(chunk.w.length / 4);
448|    for (let k = 0; k < count; k++) {
449|      const s = chunk.w[k * 4] as number;
450|      const e = chunk.w[k * 4 + 1] as number;
451|      if (s <= charOffset && charOffset < e) {
452|        return { chunk: c, word: k, t0: chunk.w[k * 4 + 2] as number };
453|      }
454|    }
455|    return null;
456|  }
457|  return null;
458|}
