460|// Playback range for a scene: t0 of the first chunk with n >= startN
461|// through t1 of the last chunk with n <= endN. Null when empty.
462|export function sceneSpan(
463|  narration: { chunks: { n: number; t0: number; t1: number }[] },
464|  startN: number,
465|  endN: number,
466|): { startSec: number; endSec: number } | null {
467|  let startSec: number | null = null;
468|  let endSec: number | null = null;
469|  for (const chunk of narration.chunks) {
470|    if (chunk.n < startN || chunk.n > endN) continue;
471|    if (startSec === null) startSec = chunk.t0;
472|    endSec = chunk.t1;
473|  }
474|  if (startSec === null || endSec === null) return null;
475|  return { startSec, endSec };
