// render, so the last observed id is compared before every scene entry.
// Band contents run inside the narration provider so the music duck
// and the read-aloud control share the controller.
function BandPlay({
  musicFailed,
  empty,
  track,
  replayNonce,
  fadeSec,
  canPrev,
  onPrev,
  canSkip,
  onSkip,
  volume,
  muted,
  onVolumeChange,
  onMutedChange,
  modes,
  current,
  onAdvance,
  onEnded,
  playlistOn,
