1|// Music duck while the voice plays: the music sits about 20 dB below
2|// the voice, ramped down over ~400 ms and back up over ~800 ms so the
3|// dip never clicks.
4|export const NARRATION_DUCK_DB = 20;
5|export const NARRATION_DUCK_DOWN_MS = 400;
6|export const NARRATION_DUCK_UP_MS = 800;
7|
8|// Effective music level while narration plays: min(music, voice * gain
9|// for -duckDb). The Player keeps applying it through its duck
10|// multiplier, so the multiplier is effective / music. Pure, so the
11|// controller and the tests share the curve.
12|export function duckMultiplier(musicLevel: number, voiceVolume: number, duckDb = NARRATION_DUCK_DB): number {
13|  if (!(musicLevel > 0)) return 1;
14|  if (!Number.isFinite(voiceVolume) || voiceVolume < 0) return 1;
15|  return Math.min(1, (voiceVolume * 10 ** (-duckDb / 20)) / musicLevel);
16|}
17|
18|// Rain and ambience duck on their own: a flat ~20 dB cut while the
19|// voice plays, so a muted music track never leaves the rain at full
20|// level under the narration.
21|export function ambienceDuckTarget(narrating: boolean, duckDb = NARRATION_DUCK_DB): number {
22|  return narrating ? 10 ** (-duckDb / 20) : 1;
23|}
24|
25|// One ramp step toward target: a linear slide of the multiplier (full
26|// 0..1 range per duration), so frame-by-frame steps land within the
27|// duration instead of easing for seconds. Pure, so the controller and
28|// the tests share the curve.
29|export function rampDuck(current: number, target: number, dtMs: number, durationMs: number): number {
30|  if (!(dtMs > 0)) return current;
31|  if (!(durationMs > 0)) return target;
32|  const step = Math.min(1, dtMs / durationMs);
33|  const diff = target - current;
34|  return Math.abs(diff) <= step ? target : current + Math.sign(diff) * step;
35|}

